/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isQuantitativeScaleName = require( '@stdlib/plot/vega/base/assert/is-quantitative-scale-name' );
var join = require( '@stdlib/array/base/join' );
var scales = require( '@stdlib/plot/vega/base/scales' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:quantitative-scale:set:type' );


// MAIN //

/**
* Sets the scale type.
*
* @private
* @param {string} value - input value
* @throws {TypeError} must be a valid scale
* @returns {void}
*/
function set( value ) {
	if ( !isQuantitativeScaleName( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', 'type', join( scales( 'quantitative' ), '", "' ), value ) );
	}
	if ( value !== this._type ) {
		debug( 'Current value: %s. New value: %s.', this._type, value );
		this._type = value;
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
